], {stdio:['ignore','ignore','ignore','pipe','pipe']});
const pending = new Map();
let id = 0;
let buffer = '';
let sessionId;
const timer = setTimeout(() => { console.error('Browser check timed out'); process.exitCode=1; browser.kill(); }, 12000);
function send(method, params={}, session) {
    const key = ++id;
    return new Promise((resolve,reject) => {
        pending.set(key,{resolve,reject});
        browser.stdio[3].write(JSON.stringify({id:key, method, params,sessionId:session})+'\\0');
    });
}
browser.stdio[4].setEncoding('utf8').on('data', chunk => {
    buffer += chunk;
    for (let end; (end=buffer.indexOf('\\0'))>=0; ) {
        const reply = JSON.parse(buffer.slice(0,end));
        buffer = buffer.slice(end+1);
        if (reply.method === 'Fetch.requestPaused') {
            const {requestId,request:{url}} = reply.params;
            const allowed = new URL(url).origin === origin;
            send(allowed?'Fetch.continueRequest':'Fetch.failRequest',
                allowed?{requestId}:{requestId,errorReason:'BlockedByClient'}, reply.sessionId);
        }
        const waiter = pending.get(reply.id);
        if (waiter) {
            pending.delete(reply.id);
            if (reply.error) waiter.reject(reply.error);
            else waiter.resolve(reply.result);
        }
    }
});
async function evaluate(expression) {
    const reply = await send('Runtime.evaluate',{expression,returnByValue:true}, sessionId);
    if (reply.exceptionDetails) throw new Error(reply.exceptionDetails.text);
    return reply.result.value;
}
async function waitFor(expression) {
    for (let attempt=0; attempt<60; attempt++) {
        if (await evaluate(expression)) return;
        await new Promise(resolve=>setTimeout(resolve,100));
    }
    throw new Error('Missing browser state: '+expression);
}
(async () => {
    const {targetId} = await send('Target.createTarget',{url:'about:blank'});
    ({sessionId} = await send('Target.attachToTarget',{targetId,flatten:true}));
    await send('Fetch.enable',{patterns:[{urlPattern:'*'}]}, sessionId);
    const navigation=await send('Page.navigate',{url:origin+'/'},sessionId);
    if (navigation.errorText) throw new Error(navigation.errorText);
    await waitFor(\"document.documentElement.dataset.hasHydrated === 'true' && "'!!document.querySelector('"'main a')\");
    const links = await evaluate(\"Array.from(document.querySelectorAll('main a'), a=>({text:a.innerText,href:a.getAttribute('href')}))\");
    console.log('Home links:',JSON.stringify(links));
    await evaluate(\"Array.from(document.querySelectorAll('main a')).find(a=>a.innerText==='Current shift manual 2.0').click()\");
    await waitFor(\""'!!document.querySelector('"'article h1')\");
    console.log('After click:',JSON.stringify(await evaluate(\"({url:location.href,lang:document.documentElement.lang,heading:document.querySelector('article h1').innerText,body:document.querySelector('article').innerText,canonical:document.querySelector('link[rel=canonical]')?.href})\")));
})().catch(error=>{console.error(error);process.exitCode=1;}).finally(()=>{clearTimeout(timer);browser.kill();});
\"\"\"
    env = dict(os.environ, XDG_CONFIG_HOME=scratch, XDG_CACHE_HOME=scratch)
    subprocess.run([\"node\", \"-e\", script, scratch], env=env, check=True)
